def evaluate_state(state_view, player_id):
    start = player_id * 6
    other = (1 - player_id) * 6
    lead = state_view.captured[player_id] - state_view.captured[1 - player_id]
    position = (state_view.board[start + 5] - state_view.board[start]) - (state_view.board[other + 5] - state_view.board[other])
    return max(-10.0, min(10.0, (2.0 * lead + 0.16 * position) / 3.0))

def evaluate_state(state_view, player_id):
    start = player_id * 6
    other = (1 - player_id) * 6
    lead = state_view.captured[player_id] - state_view.captured[1 - player_id]
    side = sum(state_view.board[start:start + 6]) - sum(state_view.board[other:other + 6])
    return max(-10.0, min(10.0, (2.0 * lead + 0.2 * side) / 3.0))

